import sys, os; sys.path.insert(0, os.path.dirname(os.path.dirname(__file__)))
from dsl import *
U("s1-u07")

L(1, "Números de 0 a 10", "Contar até dez.",
  ["Dizer e reconhecer os números de 0 a 10"],
  vocab=[V("v-nul","nul","zero","numeral"), V("v-een-num","één","um","numeral",note="Escreve-se «één» quando é número, para não confundir com o artigo «een»."),
         V("v-twee","twee","dois","numeral"), V("v-drie","drie","três","numeral"), V("v-vier","vier","quatro","numeral"),
         V("v-vijf","vijf","cinco","numeral"), V("v-zeven","zeven","sete","numeral"), V("v-negen","negen","nove","numeral"),
         V("v-tien","tien","dez","numeral")],
  ex=[("één, twee, drie","um, dois, três"),("vier, vijf, zes","quatro, cinco, seis"),("zeven, acht, negen, tien","sete, oito, nove, dez")],
  gram=[G("g-een-een","een ou één?","**een** (sem acentos, «ân») é o artigo «um/uma». **één** (com acentos, «ein») é o número 1. Os acentos só aparecem quando é preciso evitar a confusão.",
    [("een boek","um livro (artigo)"),("één boek, niet twee","um livro, não dois (número)")])],
  review=["v-zes","v-acht"],
  exs=[
    MA([("twee","dois"),("drie","três"),("vier","quatro"),("vijf","cinco"),("tien","dez")], "Números de 1 a 10.", ["v-twee","v-drie","v-vier","v-vijf","v-tien"]),
    LI("zeven", ["zeven","7"], "sete", "«zeven» ≈ «zêvâ».", ["v-zeven"]),
    LI("negen", ["negen","9"], "nove", "Dois sons guturais? Não: só o «g» do meio.", ["v-negen"]),
    MC("Quanto é «vier»?", ["*4","5|5 = vijf.","3|3 = drie."], "vier = 4.", ["v-vier"]),
    TR("pt-nl","oito", ["acht","8"], "acht, com «ch» gutural.", ["v-acht"]),
    TR("pt-nl","seis", ["zes","6"], "zes, com «z» sonoro.", ["v-zes"]),
    FB("één, twee, ___, vier", ["drie"], "1, 2, 3, 4.", ["v-drie"], choices=["drie","tien","negen"]),
    MC("Em que frase «één» é o número 1?", ["*Ik heb één broer, niet twee.","Ik heb een fiets.|Aqui «een» é só o artigo."], "«één» com acentos = número.", ["v-een-num"]),
    TR("nl-pt","twee koffie, alstublieft", ["dois cafés, por favor","2 cafés, por favor"], "Nos pedidos, «koffie» fica muitas vezes no singular: twee koffie.", ["v-twee","v-koffie"]),
    WO("cinco, quatro, três, dois, um, zero!", ["vijf,","vier,","drie,","twee,","één,","nul!"], "Contagem decrescente.", ["v-vijf","v-nul"]),
  ], diff=1, mins=4)

L(2, "Números de 11 a 20", "elf, twaalf… e os números em -tien.",
  ["Dizer os números de 11 a 20"],
  vocab=[V("v-elf","elf","onze","numeral"), V("v-twaalf","twaalf","doze","numeral"), V("v-dertien","dertien","treze","numeral"),
         V("v-veertien","veertien","catorze","numeral"), V("v-vijftien","vijftien","quinze","numeral"),
         V("v-achttien","achttien","dezoito","numeral"), V("v-twintig","twintig","vinte","numeral")],
  ex=[("elf, twaalf","onze, doze"),("dertien, veertien, vijftien","treze, catorze, quinze"),("zestien, zeventien, achttien, negentien, twintig","dezasseis… vinte")],
  gram=[G("g-tien","De 13 a 19","De 13 a 19 junta-se o número a **-tien**: vijftien, zestien, zeventien, negentien. Atenção a duas formas especiais: **dertien** (não «drietien») e **veertien** (não «viertien»).",
    [("dertien","13"),("veertien","14")])],
  review=["v-drie","v-vier","v-tien"],
  exs=[
    MA([("elf","onze"),("twaalf","doze"),("dertien","treze"),("veertien","catorze"),("twintig","vinte")], "Números de 11 a 20.", ["v-elf","v-twaalf","v-dertien","v-veertien","v-twintig"]),
    MC("Como se diz 13?", ["*dertien","drietien|É uma das formas especiais: dertien.","dertig|«dertig» = 30."], "13 = dertien.", ["v-dertien"]),
    MC("Como se diz 14?", ["*veertien","viertien|A forma correta é veertien.","veertig|«veertig» = 40."], "14 = veertien.", ["v-veertien"]),
    LI("vijftien", ["vijftien","15"], "quinze", "vijf + tien.", ["v-vijftien"]),
    LI("achttien", ["achttien","18"], "dezoito", "acht + tien: escreve-se com dois «t».", ["v-achttien"]),
    TR("pt-nl","doze", ["twaalf","12"], "twaalf.", ["v-twaalf"]),
    FE(["drie,","tien,","drietien"], 2, "dertien", "13 = dertien.", ["v-dertien"]),
    FB("tien, elf, ___", ["twaalf"], "10, 11, 12.", ["v-twaalf"], choices=["twaalf","twintig","twee"]),
    TR("nl-pt","Ik ben twintig.", ["Tenho vinte( anos)","Tenho 20( anos)"], "Para a idade usa-se «zijn» em neerlandês — veja a lição 4.", ["v-twintig"]),
    WO("onze, doze, treze", ["elf,","twaalf,","dertien"], "Sequência.", ["v-elf","v-twaalf","v-dertien"]),
  ], diff=1, mins=4)

L(3, "Dezenas e até 100", "dertig, veertig… e porque se diz «um-e-vinte».",
  ["Dizer as dezenas até 100", "Formar números como 21, 35 e 99"],
  vocab=[V("v-dertig","dertig","trinta","numeral"), V("v-veertig","veertig","quarenta","numeral"), V("v-vijftig","vijftig","cinquenta","numeral"),
         V("v-zestig","zestig","sessenta","numeral"), V("v-tachtig","tachtig","oitenta","numeral"), V("v-honderd","honderd","cem","numeral")],
  ex=[("eenentwintig","21 (um-e-vinte)"),("vijfendertig","35"),("tweeëntwintig","22","O «ë» separa as vogais."),("negenennegentig","99")],
  gram=[G("g-numeros-compostos","Unidades antes das dezenas","De 21 a 99 diz-se primeiro a **unidade**, depois **en**, depois a dezena, tudo junto: **eenentwintig** (um-e-vinte = 21), **vijfendertig** (35). Depois de vogal escreve-se **ë**: tweeëntwintig, drieëntwintig. Atenção: **tachtig** (80) começa por «t».",
    [("zevenenveertig","47"),("achtenvijftig","58")],
    "Em português dizemos «trinta e cinco»; em neerlandês, «cinco-e-trinta».")],
  review=["v-twintig","v-vijf","v-een-num","v-twee"],
  exs=[
    MA([("dertig","trinta"),("veertig","quarenta"),("vijftig","cinquenta"),("tachtig","oitenta"),("honderd","cem")], "Dezenas.", ["v-dertig","v-veertig","v-vijftig","v-tachtig","v-honderd"]),
    MC("Quanto é «vijfendertig»?", ["*35","53|A unidade vem primeiro: vijf (5) en dertig (30).","45|veertig seria 40."], "vijf-en-dertig = 35.", ["v-dertig"]),
    MC("Como se escreve 22?", ["*tweeëntwintig","tweeentwintig|Depois de «ee» escreve-se «ë».","twintigtwee|A unidade vem primeiro."], "twee + ën + twintig.", ["v-twee","v-twintig"]),
    LI("eenentwintig", ["eenentwintig","21"], "vinte e um", "een-en-twintig.", ["v-twintig"]),
    LI("achtenveertig", ["achtenveertig","48"], "quarenta e oito", "acht-en-veertig.", ["v-veertig"]),
    TR("pt-nl","oitenta", ["tachtig","80"], "80 = tachtig, com «t».", ["v-tachtig"]),
    TR("pt-nl","sessenta e cinco", ["vijfenzestig","65"], "vijf-en-zestig.", ["v-zestig"]),
    FE(["Ik","ben","dertigvijf."], 2, "vijfendertig", "A unidade vem primeiro: vijfendertig.", ["v-dertig"]),
    FB("Honderd is tien keer ___.", ["tien"], "10 × 10 = 100.", ["v-honderd","v-tien"], choices=["tien","twintig","vijf"], tr="Cem é dez vezes dez."),
    TR("nl-pt","negenennegentig", ["noventa e nove","99"], "negen-en-negentig.", ["v-negen"]),
  ], diff=2, mins=5)

L(4, "Quantos anos tens?", "Perguntar e dizer a idade; aniversários.",
  ["Perguntar e dizer a idade", "Dar os parabéns"],
  vocab=[V("v-hoe-oud","hoe oud","que idade|quantos anos","expression",note="Hoe oud ben je? = Quantos anos tens?"),
         V("v-verjaardag","verjaardag","aniversário","noun","de"), V("v-jarig","jarig","que faz anos","adjective",note="Ik ben jarig = faço anos (hoje)."),
         V("v-gefeliciteerd","gefeliciteerd","parabéns","interjection",note="Diz-se ao aniversariante e também à família dele."),
         V("v-vandaag","vandaag","hoje","adverb")],
  ex=[("Hoe oud ben je?","Quantos anos tens?"),("Ik ben vijfentwintig (jaar).","Tenho vinte e cinco anos."),("Ik ben vandaag jarig!","Faço anos hoje!"),("Gefeliciteerd!","Parabéns!")],
  gram=[G("g-idade-zijn","A idade com «zijn»","Em neerlandês **é-se** uma idade: *ik **ben** 25 (jaar)*. Não se usa «ter». Nos aniversários neerlandeses é costume dar os parabéns também aos familiares: *Gefeliciteerd met je moeder!* (parabéns pela tua mãe).",
    [("Hoe oud is hij?","Que idade tem ele?"),("Zij is tien.","Ela tem dez anos.")],
    "Português: «tenho 25 anos». Neerlandês: «sou 25 (anos)». Dizer «ik heb 25 jaar» é um erro típico.")],
  review=["v-jaar","v-oud","v-twintig","v-dertig","v-vijf"],
  exs=[
    MC("Como se pergunta a idade a um amigo?", ["*Hoe oud ben je?","Hoeveel jaar heb je?|É um decalque do português; em neerlandês usa-se «zijn».","Hoe gaat het?|Isso é «como estás?»."], "Hoe oud ben je? = quantos anos tens?", ["v-hoe-oud"]),
    TR("pt-nl","Tenho trinta anos.", ["Ik ben dertig( jaar)","Ik ben 30( jaar)"], "Idade com «zijn»: ik ben dertig.", ["v-dertig","v-hoe-oud"]),
    FE(["Ik","heb","twintig","jaar."], 1, "ben", "A idade diz-se com «zijn»: ik ben twintig jaar.", ["v-hoe-oud"]),
    MA([("verjaardag","aniversário"),("jarig","que faz anos"),("gefeliciteerd","parabéns"),("vandaag","hoje")], "Aniversários.", ["v-verjaardag","v-jarig","v-gefeliciteerd","v-vandaag"]),
    DL([("Eva","Ik ben vandaag jarig!","Faço anos hoje!"),("Tom","")], ["*Gefeliciteerd!","Graag gedaan!|Isso é «de nada».","Welterusten!|Isso é «dorme bem»."], "Parabéns = gefeliciteerd.", ["v-gefeliciteerd","v-jarig"]),
    CJ("zijn","zij","Hoe oud ___ zij?", ["is"], "Hoe oud is zij? = que idade tem ela?", ["v-hoe-oud"]),
    LI("Hoe oud is je zoon?", ["Hoe oud is je zoon"], "Quantos anos tem o teu filho?", "«je zoon» = o teu filho.", ["v-hoe-oud","v-zoon"]),
    TR("nl-pt","Mijn dochter is zeven.", ["A minha filha tem sete( anos)"], "«dochter» = filha.", ["v-zeven"]),
    EX("Gefeliciteerd met je moeder!", "Felicitado com a tua mãe!", "Na festa de anos da mãe de um amigo, dizem-lhe isto. Porquê?", ["*É costume dar os parabéns também à família","Estão a confundi-lo com a mãe|Não: é um costume neerlandês.","É uma forma de dizer adeus|Não é uma despedida."], "Nos Países Baixos felicita-se toda a família do aniversariante.", ["v-gefeliciteerd"]),
    SW("Diga a sua idade e quando faz anos (pode inventar).", ["Ik ben [dertig|twintig|veertig|vijfentwintig]( jaar)","Ik ben [dertig|twintig|veertig|vijfentwintig]( jaar)(.) Mijn verjaardag is in mei"],
       ["Usa «ik ben» + número (não «ik heb»)","O número escreve-se numa só palavra"], 3, "Modelo: «Ik ben vijfentwintig jaar.»", ["v-hoe-oud"]),
  ], diff=2, mins=6)

L(5, "Primeiro, segundo, terceiro", "Os ordinais e os dias: hoje, amanhã, ontem.",
  ["Usar ordinais até 10", "Dizer hoje, amanhã e ontem", "Dizer uma data simples"],
  vocab=[V("v-eerste","eerste","primeiro","numeral"), V("v-tweede","tweede","segundo","numeral"), V("v-derde","derde","terceiro","numeral"),
         V("v-morgen","morgen","amanhã","adverb",note="Também «de morgen» = a manhã."), V("v-gisteren","gisteren","ontem","adverb"),
         V("v-datum","datum","data","noun","de")],
  ex=[("Het is de eerste mei.","É o dia um de maio."),("Morgen is mijn verjaardag.","Amanhã é o meu aniversário."),("Gisteren was ik ziek.","Ontem estava doente.")],
  gram=[G("g-ordinais","Ordinais","Os ordinais formam-se com **-de** ou **-ste**: tweede, vierde, vijfde, zesde, zevende, negende, tiende; **achtste**, **twintigste** e a partir de 20 com -ste. Irregulares: **eerste** (1.º) e **derde** (3.º). Nas datas: *de vijfde mei* ou simplesmente *5 mei*.",
    [("de tiende","o décimo"),("de twintigste","o vigésimo")])],
  review=["v-vandaag","v-verjaardag","v-vijf","v-acht"],
  exs=[
    MA([("eerste","primeiro"),("tweede","segundo"),("derde","terceiro"),("morgen","amanhã"),("gisteren","ontem")], "Ordinais e dias.", ["v-eerste","v-tweede","v-derde","v-morgen","v-gisteren"]),
    MC("Como se diz «oitavo»?", ["*achtste","achtde|Depois de «ch» usa-se -ste: achtste.","achte|Não existe."], "acht → achtste.", ["v-acht"]),
    MC("Como se diz «terceiro»?", ["*derde","driede|É irregular: derde.","drieste|É irregular: derde."], "derde é irregular.", ["v-derde"]),
    TR("pt-nl","amanhã", ["morgen"], "«morgen» = amanhã; «de morgen» = a manhã.", ["v-morgen"]),
    TR("nl-pt","Morgen is mijn verjaardag.", ["Amanhã é o meu aniversário","Amanhã faço anos"], "morgen = amanhã.", ["v-morgen","v-verjaardag"]),
    FB("Vandaag is het de vierde, morgen is het de ___.", ["vijfde"], "4.º → 5.º: vijfde.", ["v-vijf"], choices=["vijfde","vijfste","vijf"], tr="Hoje é dia quatro, amanhã é dia cinco."),
    LI("de eerste", ["de eerste"], "o primeiro", "«eer» com «ee» longo.", ["v-eerste"]),
    AR("datum","a data","de", "«De datum».", ["v-datum"]),
    WO("Hoje é o meu primeiro dia.", ["Vandaag","is","mijn","eerste","dag"], "Começando por «vandaag», o verbo continua em segunda posição.", ["v-vandaag","v-eerste"]),
    TR("nl-pt","Gisteren was ik moe.", ["Ontem estava cansad[o|a]","Ontem eu estava cansad[o|a]"], "«was» = passado de «zijn» (estava/era).", ["v-gisteren","v-moe"]),
  ], diff=2, mins=5)

L(6, "Números de telefone e preços", "Dizer números na prática: telefone e euros.",
  ["Dizer um número de telefone", "Perceber preços em euros"],
  vocab=[V("v-telefoonnummer","telefoonnummer","número de telefone","noun","het"), V("v-euro","euro","euro","noun","de","euro's"),
         V("v-cent","cent","cêntimo","noun","de"), V("v-kosten","kosten","custar","verb",note="Wat kost…? = Quanto custa…?"),
         V("v-hoeveel","hoeveel","quanto|quantos","adverb")],
  ex=[("Wat is je telefoonnummer?","Qual é o teu número de telefone?"),("Nul zes, twaalf, vierendertig…","Zero seis, doze, trinta e quatro…"),("Wat kost het? — Drie euro vijftig.","Quanto custa? — Três euros e cinquenta.")],
  gram=[G("g-precos","Preços","Diz-se **drie euro vijftig** (€ 3,50) — «euro» fica no singular depois de um número e não se diz «e». A pergunta é **Wat kost…?** ou **Hoeveel kost…?** Os números de telemóvel começam por **06** e costumam dizer-se aos pares.",
    [("Dat is twee euro.","São dois euros."),("Wat kost de koffie?","Quanto custa o café?")],
    "Em português dizemos «três euros e cinquenta»; em neerlandês, «drie euro vijftig», sem plural nem «e».")],
  review=["v-twee","v-drie","v-vijftig","v-twaalf","v-nul"],
  exs=[
    MC("Como se diz € 2,50?", ["*twee euro vijftig","twee euro's en vijftig|Depois de um número, «euro» fica no singular e não se diz «en».","vijftig twee euro|A ordem é euros e depois cêntimos."], "twee euro vijftig.", ["v-euro"]),
    TR("nl-pt","Wat kost de koffie?", ["Quanto custa o café"], "Wat kost…? = quanto custa…?", ["v-kosten","v-koffie"]),
    TR("pt-nl","Quanto custa?", ["Wat kost het","Hoeveel kost het"], "Wat/Hoeveel kost het?", ["v-kosten","v-hoeveel"]),
    LI("Drie euro vijftig.", ["Drie euro vijftig","3,50","€ 3,50","3.50"], "Três euros e cinquenta.", "Sem «en» entre euros e cêntimos.", ["v-euro"]),
    AR("telefoonnummer","o número de telefone","het", "het nummer → het telefoonnummer.", ["v-telefoonnummer"]),
    DL([("Lukas","Wat is je telefoonnummer?","Qual é o teu número?"),("Ana","")], ["*Nul zes, twaalf, vierendertig, zesenvijftig.","Ik ben dertig.|Isso é a idade.","Drie euro vijftig.|Isso é um preço."], "Os números de telemóvel começam por 06 e dizem-se aos pares.", ["v-telefoonnummer"]),
    FB("Dat ___ vijf euro.", ["kost"], "kosten: het kost.", ["v-kosten"], choices=["kost","is kost","kosten"], tr="Isso custa cinco euros."),
    MA([("euro","euro"),("cent","cêntimo"),("hoeveel","quanto"),("kosten","custar")], "Preços.", ["v-euro","v-cent","v-hoeveel","v-kosten"]),
    FE(["Het","kost","drie","euro's."], 3, "euro", "Depois de um número: drie euro (singular).", ["v-euro"]),
    CO("dialogue","No café", "Klant: Twee koffie, alstublieft. Wat kost het?\nOber: Dat is vijf euro twintig.\nKlant: Alstublieft.\nOber: Dank u wel!",
       [("Quantos cafés pede o cliente?", ["*Dois","Um","Cinco"]),("Quanto paga?", ["*€ 5,20","€ 2,50","€ 20,05"])],
       "vijf euro twintig = € 5,20.", ["v-kosten","v-euro"]),
  ], diff=2, mins=6)

